import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static void catat(Path p, String baris) throws IOException {
        List<String> isi = Files.exists(p) ? Files.readAllLines(p) : new ArrayList<String>();
        isi.add(baris);
        Files.write(p, isi);
    }

    public static void main(String[] args) throws IOException {
        Path kas = Paths.get("kas-praktik.txt");
        Files.deleteIfExists(kas);
        catat(kas, "masuk 50000");
        catat(kas, "keluar 20000");
        System.out.println(Files.readAllLines(kas));
        catat(kas, "masuk 35000");
        System.out.println(Files.readAllLines(kas));
        int saldo = 0;
        for (String b : Files.readAllLines(kas)) {
            String[] x = b.split(" ");
            int n = Integer.parseInt(x[1]);
            if (x[0].equals("masuk")) {
                saldo += n;
            } else {
                saldo -= n;
            }
        }
        System.out.println("Saldo: " + saldo);
    }
}

