import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static void catat(Path p, String baris) throws IOException {
        List<String> isi = Files.exists(p) ? Files.readAllLines(p) : new ArrayList<String>();
        isi.add(baris);
        Files.write(p, isi);
    }

    public static void main(String[] args) throws IOException {
        Path p = Paths.get("kas-tantangan.txt");
        Files.deleteIfExists(p);
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            catat(p, in.nextLine());
        }
        List<String> isi = Files.readAllLines(p);
        int saldo = 0;
        for (String b : isi) {
            String[] x = b.split(" ");
            int n = Integer.parseInt(x[1]);
            saldo += x[0].equals("masuk") ? n : -n;
        }
        System.out.println("Transaksi: " + isi.size());
        System.out.println("Saldo: " + saldo);
    }
}
